# Generated by the start-bridge codemod for storefront; re-run it instead of editing.
"""Validate and preserve the storefront Worker artifacts; never deploy.

Reuses the reviewed Apps seal/restore implementation with this app's Worker
identity, public files and source-SHA channel.
"""
import importlib.util
import json
import os
from pathlib import Path

PROFILE = os.environ.get("VITE_STOREFRONT_NATIVE_PROFILE", "staging")
PROFILES = Path(__file__).resolve().parents[2] / "apps/storefront/cloudflare/native-profiles.json"
PUBLIC_FILES = (
    "robots.txt",
)


def load():
    profiles = json.loads(PROFILES.read_text())
    if PROFILE not in profiles:
        raise ValueError("Unknown Storefront artifact profile")
    profile = profiles[PROFILE]
    worker = profile["workerName"]
    path = Path(__file__).with_name("apps-native-artifact.py")
    spec = importlib.util.spec_from_file_location("storefront_native_artifact_base", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    module.IDENTITY = {
        **module.IDENTITY,
        "name": worker,
        "compatibility_date": "2026-10-12",
        "compatibility_flags": ["nodejs_compat","global_fetch_strictly_public"],
        "workers_dev": False,
        "preview_urls": False,
        "vars": profile["vars"],
    }
    module.NORMALIZED_DEFAULTS = {**module.NORMALIZED_DEFAULTS, "topLevelName": worker}
    if PROFILE == "production":
        module.NORMALIZED_DEFAULTS["upload_source_maps"] = False
    module.RECEIPT = "storefront-production-artifact.json" if PROFILE == "production" else "storefront-native-artifact.json"
    module.PUBLIC_FILES = PUBLIC_FILES
    return module


def main():
    # The shared CLI reads its exact source from APPS_SOURCE_SHA.
    if "STOREFRONT_SOURCE_SHA" in os.environ:
        os.environ["APPS_SOURCE_SHA"] = os.environ["STOREFRONT_SOURCE_SHA"]
    else:
        os.environ.pop("APPS_SOURCE_SHA", None)
    load().main()


if __name__ == "__main__":
    main()
